const WORD_VIEWBOX = { x: 48, y: -720, w: 3097, h: 738 };

export default function Logo({
  variant = "light",
  size = 28,
  iconOnly = false,
  ...props
}: LogoProps) {
  const gradId = useId();
  const iconW = (size * 80) / 108;
  const gap = size * 0.3;
  const fontPx = size; // wordmark font size equals the drop height
  const wordH = ((WORD_VIEWBOX.h / 1000) * fontPx);
  const wordW = (WORD_VIEWBOX.w / WORD_VIEWBOX.h) * wordH;
  const width = iconOnly ? iconW : iconW + gap + wordW;

  return (
    <svg
      viewBox={`0 0 ${width} ${size}`}
      width={width}
      height={size}
      role="img"
      aria-label="Rivulet"
      {...props}
    >
      <defs>
        <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#FFC93C" />
          <stop offset="0.35" stopColor="#FF8A3D" />
          <stop offset="0.7" stopColor="#F9605A" />
          <stop offset="1" stopColor="#E8407E" />
        </linearGradient>
      </defs>
      <svg viewBox="20 8 80 108" width={iconW} height={size}>
        <path
          d="M60 8 C60 8 20 50 20 76 A40 40 0 0 0 100 76 C100 50 60 8 60 8 Z"
          fill={`url(#${gradId})`}
        />
      </svg>
      {!iconOnly && (
        <svg
          x={iconW + gap}
          y={(size - wordH) / 2}
          width={wordW}
          height={wordH}
          viewBox={`${WORD_VIEWBOX.x} ${WORD_VIEWBOX.y} ${WORD_VIEWBOX.w} ${WORD_VIEWBOX.h}`}
        >
          <path d={WORD_PATH} fill={WORDMARK[variant]} />
        </svg>
      )}
    </svg>
  );
}
